"use strict";(globalThis.webpackChunktextbook_website=globalThis.webpackChunktextbook_website||[]).push([[964],{7058:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"textbookSidebar":[{"type":"link","href":"/ai-robotics-textbook/docs/chapter-1","label":"Chapter 1: Physical AI Foundations","docId":"chapter-1","unlisted":false},{"type":"link","href":"/ai-robotics-textbook/docs/chapter-2","label":"Chapter 2: ROS 2 Fundamentals","docId":"chapter-2","unlisted":false},{"type":"link","href":"/ai-robotics-textbook/docs/chapter-3","label":"Chapter 3: Gazebo Simulation","docId":"chapter-3","unlisted":false},{"type":"link","href":"/ai-robotics-textbook/docs/chapter-4","label":"Chapter 4: Unity Visualization","docId":"chapter-4","unlisted":false},{"type":"link","href":"/ai-robotics-textbook/docs/chapter-5","label":"Chapter 5: NVIDIA Isaac Sim & Isaac ROS","docId":"chapter-5","unlisted":false},{"type":"link","href":"/ai-robotics-textbook/docs/chapter-6","label":"Chapter 6: Humanoid Robotics + VLA Systems","docId":"chapter-6","unlisted":false}]},"docs":{"chapter-1":{"id":"chapter-1","title":"Chapter 1: Physical AI Foundations","description":"Welcome to the first chapter of our exploration into the exciting world of Physical AI. This field represents the convergence of artificial intelligence with the physical world, moving beyond purely digital realms to create systems that can perceive, reason, and act in our own environment.","sidebar":"textbookSidebar"},"chapter-2":{"id":"chapter-2","title":"Chapter 2: ROS 2 Fundamentals","description":"This chapter introduces the Robot Operating System 2 (ROS 2), the foundational software framework for modern robotics. Understanding ROS 2 is essential for anyone serious about developing sophisticated robotic applications.","sidebar":"textbookSidebar"},"chapter-3":{"id":"chapter-3","title":"Chapter 3: Gazebo Simulation","description":"In this chapter, we dive into the world of robotics simulation with Gazebo. Simulation is a critical tool in robotics, allowing for rapid prototyping, testing, and validation of algorithms without the need for physical hardware.","sidebar":"textbookSidebar"},"chapter-4":{"id":"chapter-4","title":"Chapter 4: Unity Visualization","description":"While Gazebo is a powerful tool for physics simulation, the Unity engine has emerged as a leading platform for high-fidelity rendering and creating interactive experiences. In this chapter, we\'ll explore how Unity can be used as a powerful visualization tool and even a full-fledged simulator for robotics.","sidebar":"textbookSidebar"},"chapter-5":{"id":"chapter-5","title":"Chapter 5: NVIDIA Isaac Sim & Isaac ROS","description":"In this chapter, we explore the NVIDIA Isaac ecosystem, a powerful suite of tools for developing, simulating, and deploying AI-powered robots. At the core of this ecosystem are Isaac Sim and Isaac ROS, which provide a state-of-the-art platform for building the next generation of intelligent machines.","sidebar":"textbookSidebar"},"chapter-6":{"id":"chapter-6","title":"Chapter 6: Humanoid Robotics + VLA Systems","description":"This chapter stands at the cutting edge of Physical AI, where two of the most ambitious goals in the field converge: creating agile, general-purpose humanoid robots and endowing them with the ability to understand and act upon high-level human instructions. We will explore the challenges of humanoid robotics and the transformative potential of Vision-Language-Action (VLA) systems.","sidebar":"textbookSidebar"}}}}')}}]);